DSA-Notes/Cheat-Seats/Binary-Search.content:
Custom &amp; STL (Cheatsheet)



                  Notes (short) 




Use mid = lo + (hi-lo)/2 to avoid overflow; use +1 in numerator for upper-mid.
lower_bound returns n when all elements &lt; target; check bounds.
For answer-space searches, prefer partition_point (or first_true template).



1. Exact match (index or -1)
int bs_exact(const vector&lt;int&gt;&amp; a, int target) {
  int lo = 0, hi = (int)a.size()-1;
  while (lo &lt;= hi) {
    int mid = lo + (hi-lo)/2;
    if (a[mid] == target) return mid;
    if (a[mid] &lt; target) lo = mid+1;
    else hi = mid-1;
  }
  return -1;
}

// stl
bool exists = std::binary_search(a.begin(), a.end(), target);
2. Lower bound — first index &gt;= target
Lower bound is the first occurrence of target element. If element not found index of first element greater than target is returned.
int lower_bound_idx(const vector&lt;int&gt;&amp; a, int target) {
  int lo = 0, hi = (int)a.size(); // hi = n
  while (lo &lt; hi) {
    int mid = lo + (hi-lo)/2;
    if (a[mid] &lt; target) lo = mid+1;
    else hi = mid;
  }
  return lo; // in [0..n]
}

// stl
auto it = std::lower_bound(a.begin(), a.end(), target); 
int idx = it - a.begin();
3. Upper bound — first index &gt; target
Upper bound is the first occurrence of element greater than target element.
int upper_bound_idx(const vector&lt;int&gt;&amp; a, int target) {
  int lo = 0, hi = (int)a.size();
  while (lo &lt; hi) {
    int mid = lo + (hi-lo)/2;
    if (a[mid] &lt;= target) lo = mid+1;
    else hi = mid;
  }
  return lo;
}

// stl
auto it = std::upper_bound(a.begin(), a.end(), target);
int idx = it - a.begin();
4. First true (predicate over indices / answer-space)
int first_true(int lo, int hi, auto pred) { // pred(mid) monotonic: F..F T..T
  while (lo &lt; hi) {
    int mid = lo + (hi-lo)/2;
    if (pred(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo; // check pred(lo)
}

// stl
auto it = std::partition_point(begin, end, pred_on_element);
5. Last true (use upper-mid)
int last_true(int lo, int hi, auto pred) { // pred: F..F T..T
  while (lo &lt; hi) {
    int mid = lo + (hi-lo+1)/2; // upper mid
    if (pred(mid)) lo = mid;
    else hi = mid-1;
  }
  return lo; // check pred(lo)
}
6. Count duplicates / range of equal elements
int count = upper_bound_idx(a, x) - lower_bound_idx(a, x);`  

// stl
auto r = std::equal_range(a.begin(), a.end(), x);
int count = r.second - r.first;
7. Rotated sorted array search (no duplicates)
int search_rotated(const vector&lt;int&gt;&amp; a, int target) {
  int lo=0, hi=(int)a.size()-1;
  while (lo &lt;= hi) {
    int mid = lo + (hi-lo)/2;
    if (a[mid] == target) return mid;
    if (a[lo] &lt;= a[mid]) { // left sorted
      if (a[lo] &lt;= target &amp;&amp; target &lt; a[mid]) hi = mid-1;
      else lo = mid+1;
    } else { // right sorted
      if (a[mid] &lt; target &amp;&amp; target &lt;= a[hi]) lo = mid+1;
      else hi = mid-1;
    }
  }
  return -1;
}
STL: no direct STL; use lower_bound on rotated slices after finding pivot.

