DSA-Notes/DataStructures/Segment-Tree.content:
Segment Tree — Cheatsheet (C++)
Quick facts

Purpose: fast range queries and updates over an array (sum/min/max/count, etc.).
Complexities: build O(n), query O(log n), update O(log n).
Memory: recursive implementation commonly uses ~4 * n slots; iterative uses 2 * n.
There is no segment tree in the C++ standard library — implement it or use a third-party/Boost alternative if allowed.


When to use (vs alternatives)

Use segment tree when you need both flexible range queries and updates.
Use Fenwick/BIT for simpler operations (prefix sums + point updates) — smaller and faster to write.


Variants to remember

Point update + range query (basic)
Range update + range query (requires lazy propagation)
Iterative (bottom-up) segment tree — compact and fast
2D segment trees — conceptually similar, rarely asked but good to know
Generic templates using a combine function (sum/min/max)


Templates (copy-paste ready)
1) Recursive segment tree — point update + range sum
// Recursive segment tree - point update, range sum query
#include &lt;bits/stdc++.h&gt;
using namespace std;
using ll = long long;

struct SegTree {
    int n;
    vector&lt;ll&gt; st; // size 4*n
    SegTree(const vector&lt;ll&gt;&amp; a) {
        n = (int)a.size();
        st.assign(4*n, 0);
        build(1, 0, n-1, a);
    }
    void build(int p, int l, int r, const vector&lt;ll&gt;&amp; a) {
        if (l == r) { st[p] = a[l]; return; }
        int m = (l + r) &gt;&gt; 1;
        build(p&lt;&lt;1, l, m, a);
        build(p&lt;&lt;1|1, m+1, r, a);
        st[p] = st[p&lt;&lt;1] + st[p&lt;&lt;1|1];
    }
    void update(int p, int l, int r, int idx, ll val) {
        if (l == r) { st[p] = val; return; }
        int m = (l + r) &gt;&gt; 1;
        if (idx &lt;= m) update(p&lt;&lt;1, l, m, idx, val);
        else update(p&lt;&lt;1|1, m+1, r, idx, val);
        st[p] = st[p&lt;&lt;1] + st[p&lt;&lt;1|1];
    }
    void update(int idx, ll val) { update(1, 0, n-1, idx, val); }
    ll query(int p, int l, int r, int L, int R) {
        if (L &gt; r || R &lt; l) return 0; // identity for sum
        if (L &lt;= l &amp;&amp; r &lt;= R) return st[p];
        int m = (l + r) &gt;&gt; 1;
        return query(p&lt;&lt;1, l, m, L, R) + query(p&lt;&lt;1|1, m+1, r, L, R);
    }
    ll query(int L, int R) { return query(1, 0, n-1, L, R); }
};



                  Implementation details 




Uses 0-indexed array and 1-indexed tree nodes.
Use long long for sums to avoid overflow.




2) Iterative (bottom-up) segment tree — point update + range sum (half-open ranges)
// Iterative segment tree - point update, range sum [l, r) (half-open)
struct IterSeg {
    int n;
    vector&lt;long long&gt; t; // size 2*n
    IterSeg(const vector&lt;long long&gt;&amp; a) {
        n = (int)a.size();
        t.assign(2*n, 0);
        for (int i = 0; i &lt; n; ++i) t[n+i] = a[i];
        for (int i = n-1; i &gt; 0; --i) t[i] = t[i&lt;&lt;1] + t[i&lt;&lt;1|1];
    }
    void update(int p, long long v) {
        for (t[p += n] = v; p &gt; 1; p &gt;&gt;= 1) t[p&gt;&gt;1] = t[p] + t[p^1];
    }
    long long query(int l, int r) {
        long long res = 0;
        for (l += n, r += n; l &lt; r; l &gt;&gt;= 1, r &gt;&gt;= 1) {
            if (l&amp;1) res += t[l++];
            if (r&amp;1) res += t[--r];
        }
        return res;
    }
};



                  Tip




Iterative trees prefer half-open intervals [l, r) — fewer edge cases and concise loops.




3) Lazy propagation — range add + range sum
// Lazy segment tree: range add, range sum
struct LazySeg {
    int n;
    vector&lt;long long&gt; st, lazy;
    LazySeg(const vector&lt;long long&gt;&amp; a) {
        n = (int)a.size();
        st.assign(4*n, 0);
        lazy.assign(4*n, 0);
        build(1,0,n-1,a);
    }
    void build(int p,int l,int r,const vector&lt;long long&gt;&amp; a){
        if(l==r){ st[p]=a[l]; return; }
        int m=(l+r)&gt;&gt;1;
        build(p&lt;&lt;1,l,m,a); build(p&lt;&lt;1|1,m+1,r,a);
        st[p]=st[p&lt;&lt;1]+st[p&lt;&lt;1|1];
    }
    void push(int p,int l,int r){
        if(lazy[p]==0) return;
        st[p] += lazy[p] * (r - l + 1);
        if(l != r){
            lazy[p&lt;&lt;1] += lazy[p];
            lazy[p&lt;&lt;1|1] += lazy[p];
        }
        lazy[p] = 0;
    }
    void updateRange(int p,int l,int r,int L,int R,long long val){
        push(p,l,r);
        if(L&gt;r||R&lt;l) return;
        if(L&lt;=l &amp;&amp; r&lt;=R){
            lazy[p] += val;
            push(p,l,r);
            return;
        }
        int m=(l+r)&gt;&gt;1;
        updateRange(p&lt;&lt;1,l,m,L,R,val);
        updateRange(p&lt;&lt;1|1,m+1,r,L,R,val);
        st[p] = st[p&lt;&lt;1] + st[p&lt;&lt;1|1];
    }
    long long queryRange(int p,int l,int r,int L,int R){
        if(L&gt;r||R&lt;l) return 0;
        push(p,l,r);
        if(L&lt;=l &amp;&amp; r&lt;=R) return st[p];
        int m=(l+r)&gt;&gt;1;
        return queryRange(p&lt;&lt;1,l,m,L,R) + queryRange(p&lt;&lt;1|1,m+1,r,L,R);
    }
    void updateRange(int L,int R,long long val){ updateRange(1,0,n-1,L,R,val); }
    long long queryRange(int L,int R){ return queryRange(1,0,n-1,L,R); }
};



                  Warning




For range assign operations (set to X), store an assignment flag + value rather than a single lazy add value.




Common pitfalls &amp; interview tips

Off-by-one errors — pick either 0-indexing or 1-indexing for array and be consistent.
Use long long for sums when input range / values are large.
For recursive tree, allocate 4*n to be safe; iterative uses 2*n.
Always push() pending lazy values before visiting children.
If asked about STL implementation: answer no (standard C++ has no segment_tree).


LeetCode practice checklist




Interview talking points (1–2 lines)

“A segment tree stores interval aggregates in a binary tree layout so range queries/updates run in O(log n).”
“Lazy propagation defers updates to children so range updates remain O(log n) amortized.”


Flashcards (quick mental drills)

Q: Build complexity (iterative)? — A: O(n)
Q: Typical memory allocation for recursive segtree? — A: ~4*n
Q: When to use lazy propagation? — A: When you have range updates + range queries


