Traversals
1. In-Order
graph LR;
	Left --&gt; Root --&gt; Right;

void inorder(Node* r, vector&lt;int&gt;&amp; out){
    if(!r) return;
    inorder(r-&gt;left, out);
    out.push_back(r-&gt;val);
    inorder(r-&gt;right, out);
}

vector&lt;int&gt; inorder_iter(Node* root){
    vector&lt;int&gt; res;
    stack&lt;Node*&gt; st;
    Node* cur = root;
    while(cur || !st.empty()) {
        while(cur){ st.push(cur); cur = cur-&gt;left; }
        cur = st.top(); st.pop();
        res.push_back(cur-&gt;val);
        cur = cur-&gt;right;
    }
    return res;
}
2. Pre-Order
graph LR;
	Root --&gt; Left --&gt; Right;

void preorder(Node* r, vector&lt;int&gt;&amp; out){
    if(!r) return;
    out.push_back(r-&gt;val);
    preorder(r-&gt;left, out);
    preorder(r-&gt;right, out);
}

vector&lt;int&gt; preorder_iter(Node* root){
    if(!root) return {};
    vector&lt;int&gt; res;
    stack&lt;Node*&gt; st; st.push(root);
    while(!st.empty()){
        Node* t = st.top(); st.pop();
        res.push_back(t-&gt;val);
        if(t-&gt;right) st.push(t-&gt;right);
        if(t-&gt;left)  st.push(t-&gt;left);
    }
    return res;
}
3. Post-Order
graph LR;
	Left --&gt; Right --&gt; Root;


void postorder(Node* r, vector&lt;int&gt;&amp; out){
    if(!r) return;
    postorder(r-&gt;left, out);
    postorder(r-&gt;right, out);
    out.push_back(r-&gt;val);
}

vector&lt;int&gt; postorder_iter(Node* root){
    vector&lt;int&gt; res;
    if(!root) return res;
    stack&lt;Node*&gt; st; Node* prev = nullptr;
    st.push(root);
    while(!st.empty()){
        Node* cur = st.top();
        if(!prev || prev-&gt;left == cur || prev-&gt;right == cur){
            // traversing down
            if(cur-&gt;left) st.push(cur-&gt;left);
            else if(cur-&gt;right) st.push(cur-&gt;right);
        }else if(cur-&gt;left == prev){
            if(cur-&gt;right) st.push(cur-&gt;right);
        }else{
            res.push_back(cur-&gt;val);
            st.pop();
        }
        prev = cur;
    }
    return res;
}

3. Level Order Traversal (BFS)
vector&lt;vector&lt;int&gt;&gt; levelOrder(Node* root){
    vector&lt;vector&lt;int&gt;&gt; ans;
    if(!root) return ans;
    queue&lt;Node*&gt; q; q.push(root);
    while(!q.empty()){
        int sz = q.size();
        vector&lt;int&gt; level;
        for(int i=0;i&lt;sz;i++){
            auto t = q.front(); q.pop();
            level.push_back(t-&gt;val);
            if(t-&gt;left) q.push(t-&gt;left);
            if(t-&gt;right) q.push(t-&gt;right);
        }
        ans.push_back(level);
    }
    return ans;
}

