With count
struct Trie {
    struct Node {
        array&lt;int,26&gt; nxt;
        bool end=false;
        int cnt=0; // count of words passing through
        Node(){ nxt.fill(-1); }
    };
    vector&lt;Node&gt; t;
    Trie(){ t.emplace_back(); }

    void insert(const string&amp; s){
        int v=0;
        t[v].cnt++;
        for(char ch: s){
            int c = ch-&#039;a&#039;;
            if(t[v].nxt[c]==-1){ t[v].nxt[c]=t.size(); t.emplace_back(); }
            v = t[v].nxt[c];
            t[v].cnt++;
        }
        t[v].end = true;
    }

    bool remove(const string&amp; s){
        int v=0;
        vector&lt;int&gt; path = {0};
        for(char ch: s){
            int c = ch-&#039;a&#039;;
            if(t[v].nxt[c]==-1) return false;
            v = t[v].nxt[c];
            path.push_back(v);
        }
        if (!t[v].end) return false;
        t[v].end = false;
        // decrement counts, prune nodes if cnt==0
        for (int i = (int)path.size()-1; i&gt;=0; --i){
            t[path[i]].cnt--;
            if (t[path[i]].cnt==0 &amp;&amp; i&gt;0){
                int parent = path[i-1];
                int c = s[i-1]-&#039;a&#039;;
                t[parent].nxt[c] = -1; // node becomes unreachable
            }
        }
        return true;
    }
};

// Trie - C++11 (compact, vector-based backing to reduce pointer churn)
// Supports lowercase &#039;a&#039;..&#039;z&#039;. See the end for a map-based general variant.
#include &lt;bits/stdc++.h&gt;
using namespace std;

struct Trie {
    struct Node {
        array&lt;int,26&gt; nxt;
        bool isEnd;
        int pass;               // number of words passing through this node (helps erase)
        Node(){ nxt.fill(-1); isEnd = false; pass = 0; }
    };
    vector&lt;Node&gt; t;

    Trie(){ t.emplace_back(); /* root at index 0 */ }

    // insert word (O(L))
    void insert(const string &amp;word){
        int cur = 0;
        t[cur].pass++;
        for(char ch : word){
            int c = ch - &#039;a&#039;;
            // if(c &lt; 0 || c &gt;= 26) throw runtime_error(&quot;only &#039;a&#039;..&#039;z&#039; supported in this trie&quot;);
            if(t[cur].nxt[c] == -1){
                t[cur].nxt[c] = (int)t.size();
                t.emplace_back();
            }
            cur = t[cur].nxt[c];
            t[cur].pass++;
        }
        t[cur].isEnd = true;
    }

    // exact search (O(L))
    bool search(const string &amp;word) const {
        int cur = 0;
        for(char ch : word){
            int c = ch - &#039;a&#039;;
            if(c &lt; 0 || c &gt;= 26) return false;
            if(t[cur].nxt[c] == -1) return false;
            cur = t[cur].nxt[c];
        }
        return t[cur].isEnd;
    }

    // prefix check (O(L))
    bool startsWith(const string &amp;pref) const {
        int cur = 0;
        for(char ch : pref){
            int c = ch - &#039;a&#039;;
            if(c &lt; 0 || c &gt;= 26) return false;
            if(t[cur].nxt[c] == -1) return false;
            cur = t[cur].nxt[c];
        }
        return true;
    }

    // erase one occurrence of word if present (O(L)).
    // Uses pass counts to cleanup nodes safely.
    bool erase(const string &amp;word){
        if(!search(word)) return false;
        int cur = 0;
        t[cur].pass--;
        for(char ch : word){
            int c = ch - &#039;a&#039;;
            int nxtIdx = t[cur].nxt[c];
            // nxtIdx must exist because we confirmed search(word) earlier
            cur = nxtIdx;
            t[cur].pass--;
        }
        t[cur].isEnd = false;
        // Optional: physically reclaim nodes from the vector is tricky.
        // We leave nodes in vector but pass counts let you know dead branches (pass==0).
        return true;
    }

    // Helper: collect all words from a node (useful for autocomplete)
    void collectFrom(int nodeIdx, string &amp;prefix, vector&lt;string&gt; &amp;out) const {
        if(t[nodeIdx].isEnd) out.push_back(prefix);
        for(int c = 0; c &lt; 26; ++c){
            int nxt = t[nodeIdx].nxt[c];
            if(nxt != -1 &amp;&amp; t[nxt].pass &gt; 0){
                prefix.push_back(char(&#039;a&#039; + c));
                collectFrom(nxt, prefix, out);
                prefix.pop_back();
            }
        }
    }

    // autocomplete: return up to `limit` completions with given prefix
    vector&lt;string&gt; autocomplete(const string &amp;prefix, int limit = 10) const {
        int cur = 0;
        for(char ch : prefix){
            int c = ch - &#039;a&#039;;
            if(c &lt; 0 || c &gt;= 26) return {};
            if(t[cur].nxt[c] == -1) return {};
            cur = t[cur].nxt[c];
        }
        vector&lt;string&gt; res;
        string tmp = prefix;
        collectFrom(cur, tmp, res);
        if((int)res.size() &gt; limit) res.resize(limit);
