using namespace std;

// two pointers: find a pair with given target in sorted vector
pair&lt;int,int&gt; twoPointersPair(const vector&lt;int&gt;&amp; a, int target) {
    int i = 0, j = (int)a.size()-1;
    while (i &lt; j) {
        int s = a[i] + a[j];
        if (s == target) return {i, j};
        if (s &lt; target) ++i; else --j;
    }
    return {-1,-1};
}

2) Sliding Window (fixed &amp; variable window)
When: contiguous subarrays / substrings with sum/unique count/constraints.
Complexity: O(n)
// smallest subarray with sum &gt;= S (variable window)
int smallestSubWithSumAtLeast(const vector&lt;int&gt;&amp; a, int S) {
    int n = a.size(), left = 0, sum = 0, ans = INT_MAX;
    for (int right = 0; right &lt; n; ++right) {
        sum += a[right];
        while (sum &gt;= S) {
            ans = min(ans, right - left + 1);
            sum -= a[left++];
        }
    }
    return ans == INT_MAX ? 0 : ans;
}

3) Fast &amp; Slow Pointers (linked list cycles, middle element)
When: cycles, find middle, detect loops.
Complexity: O(n), O(1) extra
struct ListNode { int val; ListNode* next; ListNode(int v=0):val(v),next(nullptr){} };

// detect cycle and find cycle start (Floyd)
ListNode* detectCycle(ListNode* head) {
    ListNode *slow=head, *fast=head;
    while (fast &amp;&amp; fast-&gt;next) {
        slow = slow-&gt;next;
        fast = fast-&gt;next-&gt;next;
        if (slow == fast) { // found loop
            slow = head;
            while (slow != fast) { slow = slow-&gt;next; fast = fast-&gt;next; }
            return slow;
        }
    }
    return nullptr;
}

4) Modified / Binary Search (order-agnostic, search-on-answer)
When: sorted arrays, monotonic predicate, minimize/maximize a condition.
Complexity: O(log n)
// classic binary search lower_bound style for predicate P(mid) (monotonic)
int binarySearchAnswer(int lo, int hi, function&lt;bool(int)&gt; P) {
    int ans = hi+1;
    while (lo &lt;= hi) {
        int mid = lo + (hi - lo)/2;
        if (P(mid)) { ans = mid; hi = mid - 1; } // try smaller
        else lo = mid + 1;
    }
    return ans;
}

