6) Union-Find (Disjoint Set Union)
When: connectivity, components, cycle detection in undirected graph, union constraints.
Complexity: ~O(α(n)) per op
struct DSU {
    vector&lt;int&gt; p, r;
    DSU(int n): p(n), r(n,0) { iota(p.begin(), p.end(), 0); }
    int find(int x) { return p[x]==x ? x : p[x] = find(p[x]); }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;
        if (r[a] &lt; r[b]) swap(a,b);
        p[b] = a;
        if (r[a] == r[b]) r[a]++;
        return true;
    }
};

7) Top K / Heaps (priority_queue)
When: running median, top-k frequent, k-closest, streaming data.
Complexity: O(n log k)
// top k largest (streaming)
vector&lt;int&gt; topK(vector&lt;int&gt;&amp; a, int k) {
    priority_queue&lt;int, vector&lt;int&gt;, greater&lt;int&gt;&gt; pq;
    for (int x : a) {
        pq.push(x);
        if ((int)pq.size() &gt; k) pq.pop();
    }
    vector&lt;int&gt; res;
    while (!pq.empty()) { res.push_back(pq.top()); pq.pop(); }
    reverse(res.begin(), res.end()); // largest first
    return res;
}

8) Graph Traversals — BFS &amp; DFS templates
When: shortest path unweighted (BFS), component search, backtracking variants (DFS).
Complexity: O(V+E)
// BFS from src in adjacency list graph (unweighted shortest distances)
vector&lt;int&gt; bfsShortest(int n, vector&lt;vector&lt;int&gt;&gt;&amp; adj, int src) {
    vector&lt;int&gt; dist(n, -1); queue&lt;int&gt;q;
    dist[src] = 0; q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) if (dist[v] == -1) {
            dist[v] = dist[u] + 1; q.push(v);
        }
    }
    return dist;
}

// DFS recursive (detect visited / parent)
void dfs(int u, vector&lt;vector&lt;int&gt;&gt;&amp; adj, vector&lt;int&gt;&amp; vis) {
    vis[u] = 1;
    for (int v : adj[u]) if (!vis[v]) dfs(v, adj, vis);
}

9) Topological Sort (Kahn - BFS)
When: scheduling, DAG order, detect cycle in directed graph.
Complexity: O(V+E)
vector&lt;int&gt; topoSortKahn(int n, vector&lt;vector&lt;int&gt;&gt;&amp; adj) {
    vector&lt;int&gt; indeg(n,0), order;
    for (int u = 0; u &lt; n; ++u) for (int v : adj[u]) indeg[v]++;
    queue&lt;int&gt; q;
    for (int i=0;i&lt;n;i++) if (indeg[i]==0) q.push(i);
    while (!q.empty()) {
        int u=q.front(); q.pop(); order.push_back(u);
        for (int v : adj[u]) if (--indeg[v]==0) q.push(v);
    }
    if ((int)order.size() != n) return {}; // cycle exists
    return order;
}

10) Dijkstra (shortest path with weights)
When: non-negative weighted graph shortest path.
Complexity: O((V+E) log V)
using pii = pair&lt;long long,int&gt;;
vector&lt;long long&gt; dijkstra(int n, vector&lt;vector&lt;pair&lt;int,int&gt;&gt;&gt;&amp; g, int src) {
    const long long INF = (1LL&lt;&lt;60);
    vector&lt;long long&gt; dist(n, INF);
    priority_queue&lt;pii, vector&lt;pii&gt;, greater&lt;pii&gt;&gt; pq;
    dist[src] = 0; pq.push({0, src});
    while (!pq.empty()) {
        auto [d,u] = pq.top(); pq.pop();
        if (d != dist[u]) continue;
        for (auto [v,w] : g[u]) {
            if (dist[v] &gt; d + w) {
                dist[v] = d + w;
                pq.push({dist[v], v});
