Binary Trie (bitwise trie) — max xor pair / query
When: find max xor with given number, pair-with-max-xor problems.
Complexity: O(31) per insert/query (for 32-bit ints)
struct BitTrie {
    struct Node { Node* nxt[2] = {nullptr,nullptr}; };
    Node* root;
    BitTrie(){ root = new Node(); }
    void insert(int x) {
        Node* p = root;
        for (int b = 31; b &gt;= 0; --b) {
            int bit = (x&gt;&gt;b)&amp;1;
            if (!p-&gt;nxt[bit]) p-&gt;nxt[bit] = new Node();
            p = p-&gt;nxt[bit];
        }
    }
    int maxXor(int x) {
        Node* p = root;
        if (!p-&gt;nxt[0] &amp;&amp; !p-&gt;nxt[1]) return 0; // empty guard
        int res = 0;
        for (int b = 31; b &gt;= 0; --b) {
            int bit = (x&gt;&gt;b)&amp;1;
            if (p-&gt;nxt[bit^1]) { res |= (1&lt;&lt;b); p = p-&gt;nxt[bit^1]; }
            else p = p-&gt;nxt[bit];
        }
        return res;
    }
};

