int longestAtMostK(vector&lt;int&gt;&amp; a, int K){
    int l=0; ll sum=0, best=0;
    for(int r=0;r&lt;(int)a.size();++r){
        sum += a[r];
        while(l&lt;=r &amp;&amp; sum&gt; K) { sum -= a[l++]; }
        best = max(best, r-l+1);
