When: DAG ordering, detect cycle.
vector&lt;int&gt; topo_kahn(const vector&lt;vector&lt;int&gt;&gt;&amp; g){
    int n = g.size();
    vector&lt;int&gt; indeg(n,0);
    for(int u=0;u&lt;n;++u) for(int v: g[u]) ++indeg[v];
    queue&lt;int&gt; q;
    for(int i=0;i&lt;n;++i) if(indeg[i]==0) q.push(i);
    vector&lt;int&gt; order;
    while(!q.empty()){
        int u=q.front(); q.pop();
        order.push_back(u);
        for(int v: g[u]) if(--indeg[v]==0) q.push(v);
