10) Segment Tree (iterative / point update range query)
When: range queries + point updates (or range updates with lazy).
struct SegTree {
    int n; vector&lt;ll&gt; t;
    SegTree(int _n): n(_n), t(2*n, 0) {}
    void build(const vector&lt;ll&gt;&amp; a){
        for(int i=0;i&lt;n;++i) t[n+i] = a[i];
        for(int i=n-1;i&gt;0;--i) t[i] = t[i&lt;&lt;1] + t[i&lt;&lt;1|1];
    }
    // set position p (0-indexed) to value
    void modify(int p, ll value){
        for(t[p+=n]=value; p&gt;1; p&gt;&gt;=1) t[p&gt;&gt;1] = t[p] + t[p^1];
    }
    // query [l,r) 0-indexed
    ll query(int l, int r){
        ll res=0;
        for(l+=n, r+=n; l&lt;r; l&gt;&gt;=1, r&gt;&gt;=1){
            if(l&amp;1) res += t[l++];
            if(r&amp;1) res += t[--r];
        }
        return res;
    }
};

